def crear_serie_general(apps, schema_editor):
    """La instalación arranca con la serie «General», con el prefijo y el
    contador que ya tenía la configuración: quien usaba el contador automático
    sigue numerando donde lo dejó. Los DeCA ya generados no se tocan."""
    ConfiguracionDeca = apps.get_model('deca', 'ConfiguracionDeca')
    SerieNumeracionDeca = apps.get_model('deca', 'SerieNumeracionDeca')
    config = ConfiguracionDeca.objects.first()
    if config:
        SerieNumeracionDeca.objects.get_or_create(
            nombre='General',
            defaults={
                'prefijo': config.prefijo_numero_automatico or 'DECA-',
                'ultimo_numero': config.ultimo_numero_automatico,
                'por_defecto': True,
            },
        )


